  var wg sync.WaitGroup
  wg.Add(2)
  go func(){ defer wg.Done(); r,_ := ComputeHistogram(d1); fmt.Println(r) }()
  go func(){ defer wg.Done(); r,_ := ComputeHistogram(d2); fmt.Println(r) }()
  wg.Wait()
